insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s01', '1.1 · Everyone measures one block', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 1, 'markdown', true, 110, 1, true, array['I can describe the spread in a set of measurements and sketch what I measured with the proportions right.']::text[], 'Cycle 1, session 1 of 5 — long.', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "b1", "type": "target", "statement": "I can describe the spread in a set of measurements and sketch what I measured with the proportions right."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–15 | Go to the fieldhouse. No preamble. Everyone puts a tape on the same block in the wall and writes down its length. Every reading goes on the board when you get back — or on a clipboard right there. |\n| 15–40 | One block, twenty numbers. Why don''t we agree? Rough face, where you hook, reading at an angle, whether you included the mortar. Test the ones you can. |\n| 40–80 | Freehand sketch of the block. No straightedge. Proportions first, then your measurements on it. |\n| 80–110 | Trade sketches. Could the other person order that block from your drawing? Count the questions they have to ask — that number is the quality of your drawing. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## One Block, Twenty Numbers\n\nEverybody measures the same block\n\n**Who**\n\n**Reading**\n\n**Who**\n\n**Reading**\n\n**Who**\n\n**Reading**\n\nTwo questions\n\n1.  We measured one block. Why don''t we agree?\n\n2.  It is sold as a 16-inch block. Nobody got 16. Write down what you think is going on. You will find out in two weeks.\n\nField sketch — the block\n\nFreehand. No straightedge. Proportions first, then your measurements on it.\n\n**Hand It Over**\n\nTrade drawings. The reader may not ask you anything until they are done. Every question they end up having to ask is a dimension you left off.\n\n**Questions**\n\n**What Was Missing**"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s02', '1.2 · Reading to 1/16', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 2, 'markdown', true, 55, 1, false, array['I can read a tape or rule to 1/16 and write it correctly.']::text[], 'Cycle 1, session 2 of 5 — short.', '{"schemaVersion": 1, "dayType": "STANDARD", "blocks": [{"id": "b1", "type": "target", "statement": "I can read a tape or rule to 1/16 and write it correctly."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Short session · ~55 min · one block", "markdown": "One movement. Your packet page for this session is on paper — do the work there."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–15 | Tallest mark is the inch. Halve down: 1/2, 1/4, 1/8, 1/16. Teach it as counting marks and naming what you counted — not as fractions. |\n| 15–40 | Nine readings in the packet. Whole number and fraction. Then reading rounds — you put one on the board, they write, reveal, score. Twenty in ten minutes. |\n| 40–55 | Back to the block. Is it 15 1/2, 15 5/8 or 15 3/4? Half the disagreement yesterday was people who could not read to a sixteenth. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Reading To 1/16\n\nReading a rule\n\nFind the tallest mark first — that is the inch. Then halve your way down.\n\nRead these — whole number and fraction\n\n**Reading**\n\n**Reading**\n\n**Reading**\n\nReading rounds — call and reveal\n\n10"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s03', '1.3 · The hook, and where the numbers go', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 3, 'markdown', true, 110, 1, true, array['I can explain why the hook slides, check whether mine is true, and dimension a drawing to convention.']::text[], 'Cycle 1, session 3 of 5 — long.', '{"schemaVersion": 1, "dayType": "LAB", "blocks": [{"id": "b1", "type": "target", "statement": "I can explain why the hook slides, check whether mine is true, and dimension a drawing to convention."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–10 | “Pull the hook on your tape.” Wait. Let them find it. |\n| 10–35 | How far does it slide? Measure it. Now measure the hook''s thickness. Same number. Then measure a door opening two ways — hooked outside, butted inside. If the hook is true they agree. |\n| 35–80 | Dimensioning conventions off the reference page. Gap at the extension line. Dimensions outside the object. Number above the line. Each dimension once. Re-dimension the block sketch properly. |\n| 80–110 | Trade again. Same sketch, second pass. Did the question count go down? |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## The Hook, And Where The Numbers Go\n\nThe hook on your tape\n\nPull it. It moves. It is supposed to.\n\nMeasure the slide\n\n**What**\n\n**Measurement**\n\nHow far the hook slides\n\nThickness of the hook itself\n\nA door opening, measured OUTSIDE (hooked)\n\nThe same opening, measured INSIDE (butted)\n\nIf the last two agree, the hook is doing its job. If they don''t, it is bent — and every measurement that tape has ever taken is off by the same amount.\n\nWhere the numbers go\n\nRe-dimension your block sketch — properly this time\n\nStraightedge allowed for the dimension lines. Every rule from the reference above.\n\n**Hand It Over**\n\nTrade drawings. The reader may not ask you anything until they are done. Every question they end up having to ask is a dimension you left off.\n\n**Questions**\n\n**What Was Missing**"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s04', '1.4 · Check it before you trust it', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 4, 'markdown', true, 55, 1, false, array['I can check an instrument before I use it.']::text[], 'Cycle 1, session 4 of 5 — short.', '{"schemaVersion": 1, "dayType": "STANDARD", "blocks": [{"id": "b1", "type": "target", "statement": "I can check an instrument before I use it."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Short session · ~55 min · one block", "markdown": "One movement. Your packet page for this session is on paper — do the work there."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–20 | Zero the caliper closed. Does it read zero? Check the tape against a known length. Inspect the hook, jaws, blade. |\n| 20–40 | Find a tool in this room that is out. Say by how much and what it costs over a day. |\n| 40–55 | An instrument you did not check is an opinion. This goes on the front of every measuring session for the rest of the year. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Check It Before You Trust It\n\nThe check\n\n☐  Zero the caliper with the jaws closed. Does it read zero?\n\n☐  Measure a known length with the tape. Does it agree?\n\n☐  Look at the hook. Bent? Worn? Loose rivets?\n\n☐  Look at the caliper jaws. Nicked? Dirty?\n\nAn instrument you did not check is an opinion, not a measurement.\n\nFind a tool in this room that is out\n\n**Tool**\n\n**Should Read**\n\n**Actually Reads**\n\n**Out By**\n\n**What That Costs Over A Day**"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s05', '1.5 · How much you trust your own numbers', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 5, 'markdown', true, 110, 1, true, array['I can state my own uncertainty as a number and choose the instrument a claimed tolerance forces on me.']::text[], 'Cycle 1, session 5 of 5 — long.', '{"schemaVersion": 1, "dayType": "LAB", "blocks": [{"id": "b1", "type": "target", "statement": "I can state my own uncertainty as a number and choose the instrument a claimed tolerance forces on me."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–25 | Estimation call first: write your guess before you measure. Then five trials on the same block face, every reading recorded. High minus low is your uncertainty. |\n| 25–45 | One object, four instruments. Record the smallest mark on each. One person five times versus five people once — which spread is bigger, and what does each one tell you? |\n| 45–80 | Draw the block again and write the tolerance you are claiming beside each dimension. Then say which instrument that tolerance forces you to use. |\n| 80–110 | Uncertainty sentence — “I trust my tape to about ______, because ______.” The blank is a number. Marzano self-rating on the Cycle 1 targets. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## How Much You Trust Your Own Numbers\n\nCall it first, then measure it — five times\n\n**My Guess**\n\n**Trial 1**\n\n**Trial 2**\n\n**Trial 3**\n\n**Trial 4**\n\n**Trial 5**\n\n**High − Low**\n\nFour instruments, one object\n\n**Instrument**\n\n**Smallest Mark**\n\n**Reading**\n\n**Use It When…**\n\nTape\n\nSteel rule\n\nCaliper\n\nFeeler gauge\n\nDraw it again — and claim a tolerance\n\nBeside every dimension, write the tolerance you are claiming. Then say which instrument that tolerance forces you to use.\n\nYour uncertainty\n\nI trust my tape measurements to about ______________, because"}, {"id": "b5", "type": "self_assessment", "capture": true, "targetIds": ["tr.u1.read-rule", "tr.u1.check-inst", "tr.u1.choose-inst", "tr.u1.repeat", "tr.u1.sketch"]}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s06', '2.1 · The block, the joint, and why it comes out even', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 6, 'markdown', true, 110, 1, true, array['I can explain how the mortar joint makes the nominal block size work out exactly, and draw a block with its joint.']::text[], 'Cycle 2, session 1 of 5 — long.', '{"schemaVersion": 1, "dayType": "LAB", "blocks": [{"id": "b1", "type": "target", "statement": "I can explain how the mortar joint makes the nominal block size work out exactly, and draw a block with its joint."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–15 | Two weeks ago you measured a block called 16 and got 15 5/8. It is still on the board. Today we find out why. |\n| 15–50 | At the wall: measure a block — 15 5/8 by 7 5/8. Now measure a mortar joint — 3/8. Add them. Exactly 16 and exactly 8, every time. The name is not the block. It is the block plus its share of the joint. The name describes the module that repeats. |\n| 50–85 | Draw a block in elevation with its joint, dimensioned. Both the actual and the nominal. Add a note naming the nominal size — that note is how a real drawing carries this. |\n| 85–110 | The same trick in lumber: measure a 2×4. Trade drawings and ask one question — could the reader order material from this? |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Why The Block Is Called 16\n\nThe block and its joint\n\nMeasure it at the wall\n\n**What**\n\n**What You Measured**\n\n**Add Them**\n\n**What It Is Called**\n\nOne block, long way + one joint\n\n16\"\n\nOne block, tall way + one joint\n\n8\"\n\nThe name of the block is not the block. It is the block plus its share of the mortar — the size of the module that repeats. Now go back to what you wrote in session 1.1.\n\nDraw a block in elevation, with its joint\n\nDimension the actual size AND the nominal size. Add a note naming the nominal — that note is how a real drawing carries this.\n\n**Hand It Over**\n\nTrade drawings. The reader may not ask you anything until they are done. Every question they end up having to ask is a dimension you left off.\n\n**Questions**\n\n**What Was Missing**"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s07', '2.2 · Boiler room — conduit and pipe you can reach', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 7, 'markdown', true, 55, 1, false, array['I can explain why a trade size names neither the inside nor the outside of a pipe or conduit.']::text[], 'Cycle 2, session 2 of 5 — short.', '{"schemaVersion": 1, "dayType": "STANDARD", "blocks": [{"id": "b1", "type": "target", "statement": "I can explain why a trade size names neither the inside nor the outside of a pipe or conduit."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Short session · ~55 min · one block", "markdown": "One movement. Your packet page for this session is on paper — do the work there."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–20 | Down to the boiler room. Everything the fieldhouse hangs out of reach is at arm''s length here. Measure the outside of a half-inch EMT — 0.706. Measure a half-inch copper — 5/8 outside. |\n| 20–40 | Neither number is a half. Copper inherited its name from old iron pipe. EMT''s trade size is roughly the biggest bundle of wire you should pull through it — a name about the contents, not the container. |\n| 40–55 | If you are boring a hole for it, which number do you use? |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Boiler Room      ·      2.3  What The Gauge Counts\n\nHalf-inch EMT\n\nHalf-inch copper\n\nMeasure the outside. Measure the wall. Work out the inside.\n\nTwelve-gauge wire\n\nGauge and area — check the rule yourself\n\n**Gauge**\n\nDIAMETER (caliper)\n\n**Area**\n\n**Area ÷ Smallest**\n\n14\n\n12\n\n10\n\nA = π r².  Three gauge steps should double the area — does it? If your ratio isn''t 2, is that the rule or your caliper?"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s08', '2.3 · What the gauge number counts', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 8, 'markdown', true, 110, 1, true, array['I can explain why a bigger gauge number means a thinner wire and use the three-steps-double-the-area rule.']::text[], 'Cycle 2, session 3 of 5 — long.', '{"schemaVersion": 1, "dayType": "LAB", "blocks": [{"id": "b1", "type": "target", "statement": "I can explain why a bigger gauge number means a thinner wire and use the three-steps-double-the-area rule."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–15 | Measure a 12-gauge wire. It is not 12 of anything. Let them hunt for what the number could be counting. |\n| 15–45 | It counts the pulls through a drawing die. More pulls, thinner wire — which is why the number runs backwards. Then measure 14, 12 and 10 with the caliper. |\n| 45–85 | Area from diameter, one worked example slowly. Compute all three, divide each by the smallest. Does three gauge steps double it? |\n| 85–110 | Their ratios will not be exactly 2. Is that the rule, or their calipers? That is Cycle 1 applied to Cycle 2. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Boiler Room      ·      2.3  What The Gauge Counts\n\nHalf-inch EMT\n\nHalf-inch copper\n\nMeasure the outside. Measure the wall. Work out the inside.\n\nTwelve-gauge wire\n\nGauge and area — check the rule yourself\n\n**Gauge**\n\nDIAMETER (caliper)\n\n**Area**\n\n**Area ÷ Smallest**\n\n14\n\n12\n\n10\n\nA = π r².  Three gauge steps should double the area — does it? If your ratio isn''t 2, is that the rule or your caliper?"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s09', '2.4 · Four names, four reasons', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 9, 'markdown', true, 55, 1, false, array['I can use nominal, actual, tolerance and deviation correctly.']::text[], 'Cycle 2, session 4 of 5 — short.', '{"schemaVersion": 1, "dayType": "STANDARD", "blocks": [{"id": "b1", "type": "target", "statement": "I can use nominal, actual, tolerance and deviation correctly."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Short session · ~55 min · one block", "markdown": "One movement. Your packet page for this session is on paper — do the work there."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–20 | Finish the table: block, lumber, copper, EMT, wire. What it is called, what it measures, and WHY the name is what it is. Four different reasons. |\n| 20–40 | Vocabulary: nominal, actual, tolerance, deviation — each in a sentence about a row of their own table. |\n| 40–55 | Marzano self-rating on the Cycle 2 targets. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Four Names, Four Reasons\n\nThe table\n\n**Material**\n\n**Called**\n\n**Measured**\n\n**Why The Name Is What It Is**\n\nConcrete block\n\n8 × 8 × 16\n\nFraming lumber\n\n2 × 4\n\nCopper tube\n\n1/2\"\n\nEMT conduit\n\n1/2\"\n\nWire\n\n12 gauge\n\nWords\n\nNominal\n\nWhat it is called.\n\nActual\n\nWhat it measures.\n\nTolerance\n\nHow far off you are allowed to be.\n\nDeviation\n\nHow far off you actually are.\n\nSp. nominal · real · tolerancia · desviación      Pt. nominal · real · tolerância · desvio"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s10', '2.5 · Does it fit, and at what scale', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 10, 'markdown', true, 110, 1, true, array['I can work out whether something fits using real dimensions, and draw the result to a stated scale.']::text[], 'Cycle 2, session 5 of 5 — long.', '{"schemaVersion": 1, "dayType": "LAB", "blocks": [{"id": "b1", "type": "target", "statement": "I can work out whether something fits using real dimensions, and draw the result to a stated scale."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–30 | Measure the core of a block. Now: what would actually fit down it — a 2\" drain? A run of EMT? Use real dimensions, not names. Then the classic: a nominal 2\" drain in a nominal 2×4 wall. |\n| 30–80 | Scale. Half size, quarter size, and what the scale note on a drawing means. Draw the block in section with the service in it, to a stated scale, dimensioned. |\n| 80–110 | Trade. Put a rule on the other person''s drawing and check whether it is really at the scale it claims. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Does It Fit, And At What Scale\n\nA 2-inch drain in a 2×4 wall\n\nDoes it fit?\n\n**Given**\n\n**Work**\n\n**Answer**\n\nDraw it in section, to scale\n\nState your scale in a note. Half size, quarter size — your choice, but say which.\n\nCheck somebody else''s scale\n\n**Scale They Claimed**\n\n**Scale You Measured**\n\nPut a rule on their drawing and check. A drawing that lies about its scale is worse than one with no scale at all."}, {"id": "b5", "type": "self_assessment", "capture": true, "targetIds": ["tr.u1.nominal", "tr.u1.vocab", "tr.u1.fits", "tr.u1.gauge", "tr.u1.dimension", "tr.u1.scale"]}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s11', '3.1 · The layout race, and the mason''s error', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 11, 'markdown', true, 110, 1, true, array['I can explain why error piles up on a chain and not from a datum, and find that error in real masonry.']::text[], 'Cycle 3, session 1 of 5 — long.', '{"schemaVersion": 1, "dayType": "LAB", "blocks": [{"id": "b1", "type": "target", "statement": "I can explain why error piles up on a chain and not from a datum, and find that error in real masonry."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–30 | Twelve feet on the fieldhouse floor, sixteen on center. Assign the method — half the crews measure each mark from the last one, half from one fixed end. Check where the last mark landed against 176 inches. |\n| 30–65 | Now the same thing in the wall. Count ten courses. Predict the height — ten times eight is eighty. Go measure it. If it is off, divide the miss by ten: that is the mason''s average joint error, and it accumulated exactly the way your chain did. |\n| 65–110 | Draw the layout as a dimensioned plan. Chain or datum — your drawing will show which one you used, and the next person has to get it right from it. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## The Layout Race, And The Mason''S Error\n\nTwo ways to lay out the same twelve feet\n\nOn the floor — where did your last mark land?\n\n**Method**\n\n**Spec**\n\n**Where It Landed**\n\n**Off By**\n\nChain — from the last mark\n\n176\"\n\nDatum — from one end\n\n176\"\n\nOn the wall — the same thing, done by a mason\n\n**What**\n\n**Your Number**\n\nCourses counted\n\nPredicted height (courses × 8\")\n\nMeasured height\n\nMiss ÷ courses = average joint error\n\nNobody measured badly — not you, and not the mason. Every reading carried a small error and one method adds them up.\n\nDraw the layout as a dimensioned plan\n\nSomebody else lays out a second run from your drawing. Dimension it so they get it right.\n\n**Hand It Over**\n\nTrade drawings. The reader may not ask you anything until they are done. Every question they end up having to ask is a dimension you left off.\n\n**Questions**\n\n**What Was Missing**"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s12', '3.2 · Why sixteen — and why it is the same sixteen', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 12, 'markdown', true, 55, 1, false, array['I can explain why framing is sixteen on center and why the block module is the same module.']::text[], 'Cycle 3, session 2 of 5 — short.', '{"schemaVersion": 1, "dayType": "STANDARD", "blocks": [{"id": "b1", "type": "target", "statement": "I can explain why framing is sixteen on center and why the block module is the same module."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Short session · ~55 min · one block", "markdown": "One movement. Your packet page for this session is on paper — do the work there."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–20 | Why sixteen and not fifteen? Forty-eight and ninety-six divide by it, so sheet goods land on framing. Why to centers? So the sheet edge gets half a stud and the next sheet gets the other half. |\n| 20–40 | Now the connection: a block is nominally sixteen long. A stud bay is sixteen on center. They are the same grid, and that is not a coincidence — the whole building is on a four-inch module. |\n| 40–55 | What would break if block were fifteen and framing were sixteen? |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Why Sixteen — And Why It Is The Same Sixteen\n\nSixteen on center\n\nAnswer these\n\n1.  How many 16-inch spaces fit in a 4-foot sheet?\n\n2.  Why is it measured to the centers of the studs and not their edges?\n\n3.  A block is nominally 16 inches long. A stud bay is 16 inches on center. Is that a coincidence?"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s13', '3.3 · Measuring what you cannot reach', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 13, 'markdown', true, 110, 1, true, array['I can dimension something out of reach by counting a known module, and produce three views of something I can reach.']::text[], 'Cycle 3, session 3 of 5 — long.', '{"schemaVersion": 1, "dayType": "LAB", "blocks": [{"id": "b1", "type": "target", "statement": "I can dimension something out of reach by counting a known module, and produce three views of something I can reach."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–40 | The joist bearing is thirty feet up and your tape is twenty-five. Count courses to it. Thirteen courses is a hundred and four inches, and you never left the floor. Then find two more things up there you can dimension the same way. |\n| 40–85 | Three orthographic views of something you CAN reach — a bollard, a base plate, a floor box, a bracket. Top above front, side beside it, and they line up. Straightedges from here on. |\n| 85–110 | Your drawing goes on the table with the objects. Somebody else picks yours out of the pile using the drawing alone. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Measuring What You Cannot Reach\n\nCount the module\n\nThree things overhead, dimensioned from the floor\n\n**What It Is**\n\n**Courses Counted**\n\n× 8\" =\n\n**How Sure Are You?**\n\nYou never left the ground. What else up there has a size you already know?\n\nHow the three views line up\n\nYour object — three views, dimensioned, scale noted\n\nTop above front. Side beside it. They line up. A dashed line is an edge you cannot see from where you are standing. Straightedges from here on.\n\nThe test\n\nYour drawing goes on the table with the objects. Somebody else picks yours out of the pile using the drawing alone.\n\nDid they get it right?     YES  /  NO\n\nIf not — which view was missing, or which dimension?"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s14', '3.4 · Tolerance', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 14, 'markdown', true, 55, 1, false, array['I can decide in or out, and say by how much.']::text[], 'Cycle 3, session 4 of 5 — short.', '{"schemaVersion": 1, "dayType": "STANDARD", "blocks": [{"id": "b1", "type": "target", "statement": "I can decide in or out, and say by how much."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Short session · ~55 min · one block", "markdown": "One movement. Your packet page for this session is on paper — do the work there."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–15 | Plus or minus what, and who decides. A mason''s joint tolerance is not a machinist''s. The tolerance follows the consequence of being wrong. |\n| 15–40 | Cut a go/no-go gauge out of cardboard for a stated dimension and tolerance. Then test the class''s pieces with it. It fits or it doesn''t — no argument, no judgment call. |\n| 40–55 | The sort in the packet. Five specs, five measurements. In or out, and by how much. Fractions, no calculator. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Tolerance\n\nTolerance\n\nTolerance is decided by what happens if you are wrong.\n\nCut a go / no-go gauge\n\nA go/no-go gauge has two ends. One that MUST fit, and one that must NOT.\n\nSpec: ______________     Tolerance: ______________\n\nGO end cut to ______________     NO-GO end cut to ______________\n\nNeither end is cut to the spec. Work out why before you cut.\n\nIn or out?\n\n**Spec**\n\n**Tolerance**\n\n**Measured**\n\n**In / Out**\n\n**Off By**\n\n16\"\n\n± 1/16\"\n\n16 1/8\"\n\n8\"\n\n± 1/16\"\n\n7 15/16\"\n\n48\"\n\n± 1/8\"\n\n47 15/16\"\n\n15 5/8\"\n\n± 1/32\"\n\n15 21/32\"\n\n104\"\n\n± 1/4\"\n\n104 3/8\""}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu1-s15', '3.5 · Mastery task — as-built of the wall', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'trades-1', 15, 'markdown', true, 110, 1, true, array['I can verify what is there against a drawing and produce an as-built of what is actually there.']::text[], 'Cycle 3, session 5 of 5 — long.', '{"schemaVersion": 1, "dayType": "TRANSFER", "blocks": [{"id": "b1", "type": "target", "statement": "I can verify what is there against a drawing and produce an as-built of what is actually there."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–20 | THE WALK. No drawing yet. They go to the bay and fill in the scope sheet — what the job is, what is actually there, what has to be true to call it done, what they are stuck with, what code says, what they are not doing, what they still need to know. |\n| 20–30 | NOW hand out your drawing. Read the four scoring dimensions aloud. They already know them. |\n| 30–70 | Instrument check first — the routine from 1.4. Then survey the bay: coursing, wall height by count, conduit runs and their supports, pipe and its fall, boxes located. Eight items with spec, tolerance and deviation. |\n| 70–90 | Write the inspection. What is out, what matters most, and how much you trust your own numbers — with a number. |\n| 90–110 | Produce the as-built: what is actually there, dimensioned, scale noted, nominal materials named in a note. Self-score before handing it in. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n**The Walk — before you price it, look at it**\n\nBefore you price it, look at it\n\nNobody prices a job off the phone call. You go and look first.\n\nToday the job is one bay of the fieldhouse wall and the services running past it. Go and look at it before anybody hands you a drawing of it.\n\nFill this in BEFORE anybody hands you a drawing. You want your own read of the place before a piece of paper tells you what to expect — because once you have read the drawing, you will start seeing what it says instead of what is there.\n\n1.  WHAT THEY ASKED FOR\n\nIn their words, not yours. Write what you were actually told.\n\n2.  WHAT I FOUND WHEN I LOOKED\n\nConditions. What is really there — not what you expected to be there.\n\n3.  WHAT IT HAS TO DO TO BE CALLED DONE\n\nIf you cannot say this, you cannot tell when you have finished.\n\n4.  WHAT I AM STUCK WITH\n\nThe things you cannot change. Space, access, what is already installed, what somebody else owns.\n\n5.  WHAT CODE SAYS ABOUT IT\n\nSomebody already decided part of this for you. Write the number.\n\n6.  WHAT I AM NOT DOING\n\nThe line around the job. This is where people get burned.\n\n7.  WHAT I NEED TO KNOW BEFORE I START\n\nThe question you ask now instead of the mistake you make later.\n\nSign it\n\nWalked by ______________________\n\nDate ______________________\n\nA job you did not walk is a phone call. Everything on the rest of this task comes off this page.\n\n## Mastery Task — As-Built Of The Wall\n\nThe job\n\nYou are handed a drawing of one bay of the fieldhouse wall and the services on it. Verify it, then draw what is actually there.\n\nMeasure it yourself. Decide what is in and what is out. Write an inspection another tradesman could act on. Then produce an as-built of the bay as it really is.\n\nHow this is scored\n\nScience\n\nMeasurements correct, instrument suited to the precision, recorded to the right fraction.\n\nReasoning\n\nIn-and-out calls follow from the numbers you took. Uncertainty is a number, not a feeling.\n\nCommunication\n\nAnother tradesman could build from your as-built without asking you anything.\n\nTransfer\n\nHolds up on a real job — nominal and actual handled right, consequence of being out named.\n\nYour survey\n\n**What**\n\n**On The Drawing**\n\n**Tol**\n\n**Measured**\n\n**In / Out**\n\n**Off By**\n\nYour inspection\n\n1. What is out.\n\nThe drawing is wrong on ______ items. They are:\n\n2. What matters most.\n\nThe one that matters is ________________, because\n\n3. Your uncertainty.\n\nI measured with a ____________. My spread on repeats was ______, so I trust these to about ______.\n\nAs-built — draw what is actually there\n\nNot what the drawing said. What you measured. Dimensioned, scale noted, nominal materials named in a note. Anything you counted rather than reached, say so."}, {"id": "b5", "type": "self_assessment", "capture": true, "targetIds": ["tr.u1.datum", "tr.u1.cumul", "tr.u1.sixteen", "tr.u1.tolerance", "tr.u1.views", "tr.u1.asbuilt", "tr.u1.the-walk"]}, {"id": "b6", "type": "transfer_prompt", "masteryTaskSlug": "tr.u1.mastery-as-built"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s01', '1.1 · Every riser in the flight', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 1, 'markdown', true, 110, 1, true, array['I can measure a repeated dimension across a run, describe the spread, and sketch what I measured.']::text[], 'Cycle 1, session 1 of 5 — long.', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "b1", "type": "target", "statement": "I can measure a repeated dimension across a run, describe the spread, and sketch what I measured."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–15 | Go to the stair. No preamble. Every student measures every riser in one flight, top to bottom, and writes each one down in order. Then the treads. |\n| 15–40 | Back in the room, all the numbers go on the board. They will not agree with each other and — more importantly — the risers will not agree with EACH OTHER. Find the biggest and the smallest in the flight. Subtract. That number goes in a box on the board and stays there. |\n| 40–80 | Sketch the flight in section — freehand, no straightedge. Proportions first. Then put your riser numbers on it, in order. |\n| 80–110 | Trade sketches. Could the other person build this flight from your drawing? Count the questions they have to ask. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Every Riser In The Flight\n\nMeasure every riser, bottom to top — in order\n\n**Riser #**\n\n**Height**\n\n**Riser #**\n\n**Height**\n\n**Riser #**\n\n**Height**\n\n11\n\n12\n\n13\n\n14\n\n10\n\n15\n\nNow the spread\n\n**What**\n\n**Your Number**\n\nBiggest riser in the flight\n\nSmallest riser in the flight\n\nBIGGEST − SMALLEST  =  the spread\n\nWhere in the flight were the odd ones?\n\nTwo questions\n\n1.  Is that spread YOU, or is it the STAIR? How could you tell the difference?\n\n2.  How far apart do you think they are ALLOWED to be? Write a number. You will find out in a month.\n\nField sketch — the flight, in section\n\nFreehand. No straightedge. Get the shape right first, then put your riser numbers on it in order.\n\n**Hand It Over**\n\nTrade drawings. The reader may not ask you anything until they are done. Every question they end up having to ask is a dimension you left off.\n\n**Questions**\n\n**What Was Missing**"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s02', '1.2 · Why the bubble knows', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 2, 'markdown', true, 55, 1, false, array['I can explain why a bubble finds level and why the vial is curved.']::text[], 'Cycle 1, session 2 of 5 — short.', '{"schemaVersion": 1, "dayType": "STANDARD", "blocks": [{"id": "b1", "type": "target", "statement": "I can explain why a bubble finds level and why the vial is curved."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Short session · ~55 min · one block", "markdown": "One movement. Your packet page for this session is on paper — do the work there."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–15 | Hand out levels. “What is actually in there, and why does it move?” Let them get to air on their own. |\n| 15–40 | Air is the least dense thing in the vial, so it goes as high as the glass allows. Then the real question: why is the vial curved? A straight tube has no single high point — the bubble could sit anywhere. The curve is what turns a bubble into a reading. |\n| 40–55 | Tip a level slowly and watch which way the bubble runs. Uphill, every time. Write the rule in your own words. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Why The Bubble Knows\n\nThe bubble runs uphill\n\nAnswer these\n\n1.  What is actually inside the vial, and why does the bubble move at all?\n\n2.  If the tube were perfectly STRAIGHT, where would the bubble sit?\n\n3.  So what is the curve for?"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s03', '1.3 · Two ways to find the same line', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 3, 'markdown', true, 110, 1, true, array['I can establish plumb and level three ways and say what each instrument is referenced to.']::text[], 'Cycle 1, session 3 of 5 — long.', '{"schemaVersion": 1, "dayType": "LAB", "blocks": [{"id": "b1", "type": "target", "statement": "I can establish plumb and level three ways and say what each instrument is referenced to."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–20 | Make a plumb bob: string and any weight. Hang it. It is now pointing at the centre of the earth and there is nothing you can do to it to make that untrue. |\n| 20–55 | Three instruments, one line. Plumb bob on a wall. Spirit level on the same wall. Water level between two points twenty feet apart. Do they agree? Over four feet they all agree. Over twenty feet they start to separate — and the water level is the one to believe. |\n| 55–95 | Draw the setup in elevation — the wall, the instrument, the reference line — dimensioned. This is the first section-type drawing in the course. |\n| 95–110 | One sentence: what is a laser level referenced to, and why does that make it different from the bob? |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Two Ways To Find The Same Line\n\nThree instruments, one reference\n\nSame wall, three instruments — do they agree?\n\n**Instrument**\n\n**What It Is Referenced To**\n\n**Over 4 Ft**\n\n**Over 20 Ft**\n\nPlumb bob\n\nSpirit level\n\nWater level\n\nOver four feet they will all agree. Over twenty feet they will not — and one of them is still telling the truth.\n\nDraw the setup in elevation\n\nThe wall, the instrument, the reference line. Dimensioned. Straightedge from here on.\n\nOne sentence\n\nA plumb bob is referenced to ______________________. A laser level is referenced to ______________________ — which is why one of them can be wrong and the other cannot."}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s04', '1.4 · What a laser cannot check about itself', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 4, 'markdown', true, 55, 1, false, array['I can check a level for calibration by reversing it end for end.']::text[], 'Cycle 1, session 4 of 5 — short.', '{"schemaVersion": 1, "dayType": "STANDARD", "blocks": [{"id": "b1", "type": "target", "statement": "I can check a level for calibration by reversing it end for end."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Short session · ~55 min · one block", "markdown": "One movement. Your packet page for this session is on paper — do the work there."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–20 | Set a level on a surface. Note which side of the ROOM the bubble sits. Now pick it up, turn it end for end, put it back in the same place. Where is the bubble now? |\n| 20–40 | If the bubble stayed on the same side of the room, the level is true and the surface is out. If the bubble followed the tool, the level itself is out — and half of what you read is the tool. Run the check on every level in the room. |\n| 40–55 | Which of these instruments can check itself: plumb bob, spirit level, water level, laser? Argue it. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## What A Laser Cannot Check About Itself\n\nThe reversal check\n\nRun the check on every level in the room\n\n**Level**\n\n**Reading 1**\n\nREADING 2 (reversed)\n\n**Tool Or Surface?**\n\nWhich of these can check itself?\n\nPlumb bob        Spirit level        Water level        Laser level\n\nCircle the ones that can. Then say what makes the difference."}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s05', '1.5 · Square is not free', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 5, 'markdown', true, 110, 1, true, array['I can lay out a right angle with 3-4-5 and verify a rectangle with its diagonals.']::text[], 'Cycle 1, session 5 of 5 — long.', '{"schemaVersion": 1, "dayType": "LAB", "blocks": [{"id": "b1", "type": "target", "statement": "I can lay out a right angle with 3-4-5 and verify a rectangle with its diagonals."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–15 | The break: plumb and level are GIVEN to you — the earth supplies them free. Square is not. Nothing in nature points at 90°. You have to build it. |\n| 15–60 | Lay out a rectangle on the floor with masking tape — call it 6 ft × 8 ft. No square, no framing square, nothing but tapes. Get the first corner with 3-4-5, then run the sides. |\n| 60–90 | Now verify it — measure both diagonals. Equal means square. Record how far off you were. Then deliberately rack a second rectangle and show that all four sides are still the right length. |\n| 90–110 | Draw your layout as a dimensioned plan, and put the diagonal on it as a check dimension. Trade, and have somebody verify your rectangle from your drawing alone. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Square Is Not Free\n\nBuilding it, and checking it\n\nYour layout — 6 ft × 8 ft, no square allowed\n\n**What**\n\n**Should Be**\n\n**What You Got**\n\n**Off By**\n\nSide A\n\n6 ft 0 in\n\nSide B\n\n8 ft 0 in\n\nDiagonal 1\n\n10 ft 0 in\n\nDiagonal 2\n\n10 ft 0 in\n\n**Diagonal 1 − Diagonal 2**\n\n3-4-5 BUILDS the angle. Equal diagonals PROVE it stayed. Those are two different jobs and you did both.\n\nThe racked rectangle\n\nPush your rectangle out of square on purpose. Now measure all four sides again.\n\nAre the four sides still the right length?      YES  /  NO\n\nSo why can a tape on the sides never catch this?\n\nDraw your layout as a dimensioned plan\n\nPut the diagonal on it as a check dimension. Somebody else has to verify your rectangle from this drawing alone.\n\n**Hand It Over**\n\nTrade drawings. The reader may not ask you anything until they are done. Every question they end up having to ask is a dimension you left off.\n\n**Questions**\n\n**What Was Missing**"}, {"id": "b5", "type": "self_assessment", "capture": true, "targetIds": ["tr.u2.plumb-level", "tr.u2.gravity-ref", "tr.u2.bubble", "tr.u2.level-check", "tr.u2.square-check", "tr.u2.345"]}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s06', '2.1 · Quarter inch per foot, on a real run', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 6, 'markdown', true, 110, 1, true, array['I can set and check a slope in inches per foot on a real installed run.']::text[], 'Cycle 2, session 1 of 5 — long.', '{"schemaVersion": 1, "dayType": "LAB", "blocks": [{"id": "b1", "type": "target", "statement": "I can set and check a slope in inches per foot on a real installed run."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–20 | Down to the boiler room. Find a horizontal drain or condensate run. It looks level. It is not, and it must not be. |\n| 20–65 | Measure the fall on a real run. Two ways: (1) level held against the pipe, shim one end until the bubble centres, measure the shim; (2) measure the pipe height off a level reference at two points a known distance apart, subtract. Convert to inches per foot. Do both — they should agree. |\n| 65–95 | Is it in code? Minimum is 1/4 inch per foot for pipe 2 1/2 inches and smaller; 1/8 inch per foot for 3 through 6 inch. Compare, decide, say by how much. This is the Unit 1 tolerance target on a new quantity. |\n| 95–110 | Sketch the run in elevation with the fall called out and the two end heights dimensioned. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Quarter Inch Per Foot, On A Real Run\n\nTwo ways to measure a fall — do both\n\nMETHOD 1 — SHIM IT.  Hold a level against the pipe. Shim one end until the bubble centres. Measure the shim, and measure the length of the level. That is your rise over that run.\n\nMETHOD 2 — TWO HEIGHTS.  Measure from a level reference down to the pipe at two points a known distance apart. Subtract.\n\nThe run you measured\n\n**Method 1 — Shim**\n\n**Method 2 — Two Heights**\n\nRise (drop)\n\nRun (distance)\n\nRise ÷ run, in inches per foot\n\nDo your two methods agree?\n\nIs it in code?\n\n**What**\n\n**Your Answer**\n\nPipe size (nominal)\n\nCode minimum for that size\n\nWhat you measured\n\nIN or OUT — and by how much\n\nThe code numbers\n\n2 1/2 inches and smaller\n\n1/4 inch per foot minimum\n\n3 through 6 inches\n\n1/8 inch per foot minimum\n\n8 inches and larger\n\n1/16 inch per foot minimum\n\nBigger pipe needs LESS slope, not more. Hold that thought — you will find out why in Unit 4."}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s07', '2.2 · Four trades, four units, one ratio', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 7, 'markdown', true, 55, 1, false, array['I can convert between inches per foot, pitch, percent grade and 1-in-N.']::text[], 'Cycle 2, session 2 of 5 — short.', '{"schemaVersion": 1, "dayType": "STANDARD", "blocks": [{"id": "b1", "type": "target", "statement": "I can convert between inches per foot, pitch, percent grade and 1-in-N."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Short session · ~55 min · one block", "markdown": "One movement. Your packet page for this session is on paper — do the work there."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–15 | Rise over run. One triangle on the board. Then four labels for the same triangle: a plumber''s 1/4 inch per foot, a carpenter''s 4 in 12, an excavator''s 8.3 percent, a ramp at 1:12. |\n| 15–40 | The conversion table in the packet. Every row is the same slope in four costumes. Fractions by hand for the first half; calculators for the percent column. |\n| 40–55 | Which trade uses which, and why does each one use the units it uses? A roofer works in twelves because a framing square has twelve inches on the tongue. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Four Trades, Four Units, One Ratio\n\nThe same triangle, four sets of words\n\nFill in the table — every row is one slope, four ways\n\n**Inches Per Foot**\n\n**Rise In 12**\n\n**Percent**\n\n**1 In N**\n\n**Where You See It**\n\n1/4\"\n\n1 in 48\n\ndrain\n\n1/8\"\n\nbig drain\n\n4 in 12\n\nroof\n\n1 in 12\n\nramp\n\n2 %\n\nparking lot\n\n1\"\n\nOne row is done for you. A quarter inch per foot means a quarter inch of drop for every twelve inches along — so 1 over 48. Fractions by hand; calculator for the percent column only."}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s08', '2.3 · Too flat and too steep both clog', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 8, 'markdown', true, 110, 1, true, array['I can test how slope affects what a pipe carries, and explain why there is a maximum as well as a minimum.']::text[], 'Cycle 2, session 3 of 5 — long.', '{"schemaVersion": 1, "dayType": "LAB", "blocks": [{"id": "b1", "type": "target", "statement": "I can test how slope affects what a pipe carries, and explain why there is a maximum as well as a minimum."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–25 | Build the rig: a trough on a bench, one end on blocks, a tray underneath. Set the slope by measuring rise over run and converting to inches per foot. Nobody guesses an angle — everyone sets a number. |\n| 25–75 | Run the test at 1/16, 1/8, 1/4, 1/2, 1 and 2 inches per foot. Same water, same solids, every time. Record what the water did and what the solids did SEPARATELY — that is the whole experiment. |\n| 75–110 | Graph it: slope across the bottom, how far the solids travelled up the side. There is a window, and it has two edges. Then the sentence: too flat, nothing has the energy to move; too steep, the water outruns the solids and leaves them stranded on the pipe wall. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Too Flat And Too Steep Both Clog\n\nBoth ends of the range fail\n\nSet the slope by the NUMBER — never by eye\n\n**Slope Set**\n\n**Rise**\n\n**Run**\n\n**Did The Water Move?**\n\n**How Far Did The Solids Get?**\n\n1/16\" / ft\n\n1/8\" / ft\n\n1/4\" / ft\n\n1/2\" / ft\n\n1\" / ft\n\n2\" / ft\n\nRecord the water and the solids SEPARATELY. That separation is the whole experiment.\n\nGraph it — slope across the bottom, how far the solids got up the side\n\nLabel both axes with units. Mark the window where it works, and mark both edges.\n\nTwo failures, two different reasons\n\nTOO FLAT — what failed, and why:\n\nTOO STEEP — what failed, and why:\n\nThe code prints a MINIMUM. Nobody prints the maximum. Why not?"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s09', '2.4 · What the fall costs you', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 9, 'markdown', true, 55, 1, true, array['I can work out the total fall over a run and say what it costs in depth.']::text[], 'Cycle 2, session 4 of 5 — short.', '{"schemaVersion": 1, "dayType": "STANDARD", "blocks": [{"id": "b1", "type": "target", "statement": "I can work out the total fall over a run and say what it costs in depth."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Short session · ~55 min · one block", "markdown": "One movement. Your packet page for this session is on paper — do the work there."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–15 | Twenty-two feet at a quarter inch per foot. How much does the pipe drop end to end? Do it before anybody says a number out loud. |\n| 15–40 | Five runs in the packet, five answers. Then the second column: where does that fall come from? A 5 1/2 inch drop inside a 9 1/4 inch joist bay leaves you very little, and the conduit is already in there. |\n| 40–55 | The reverse question, which is the one that comes up on a job: “I have 4 inches of depth to play with. How long a run can I get?” |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## What The Fall Costs You\n\nIt has to come out of somewhere\n\nTotal fall — no calculators\n\n**Run**\n\n**Slope**\n\n**Total Fall**\n\n**Fits In A 2×10 Bay (9 1/4\")?**\n\n22 ft\n\n1/4\" / ft\n\n16 ft\n\n1/4\" / ft\n\n40 ft\n\n1/8\" / ft\n\n8 ft\n\n1/2\" / ft\n\n34 ft\n\n1/4\" / ft\n\nThe question that actually comes up on a job\n\n**Given**\n\nYou have 4 inches of depth to play with, and the drain has to run at 1/4 inch per foot.\n\n**Work**\n\n**Answer**\n\nJoist depths, actual:  2×8 = 7 1/4\"   ·   2×10 = 9 1/4\"   ·   2×12 = 11 1/4\".  Nominal is not the size — you knew that already."}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s10', '2.5 · Draw the fall', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 10, 'markdown', true, 110, 1, true, array['I can draw a sloped run in plan and in section with the fall called out correctly.']::text[], 'Cycle 2, session 5 of 5 — long.', '{"schemaVersion": 1, "dayType": "LAB", "blocks": [{"id": "b1", "type": "target", "statement": "I can draw a sloped run in plan and in section with the fall called out correctly."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–30 | A plan shows you where. A section shows you how deep. A slope is invisible in plan — which is why it gets called out in a note and dimensioned in section. Both, for the same run. |\n| 30–80 | Draw the run you measured in the boiler room, to a stated scale: plan with the fall noted, section with both end elevations dimensioned. Every Unit 1 dimensioning rule still applies. |\n| 80–110 | Trade. The reader has to state, from the drawing alone, the fall per foot and the elevation at both ends. If they cannot, something is missing. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Draw The Fall\n\nWhy it takes two drawings\n\nA PLAN shows you where a run goes. A SECTION shows you how deep it sits.\n\nA slope is invisible in plan — from above, a pipe falling a quarter inch per foot looks exactly like one that is dead level. That is why the fall gets written in a note on the plan and dimensioned in the section. If you only draw one of them, the person building it has to guess.\n\nPLAN — where the run goes\n\nCall the fall out in a note. State your scale.\n\nSECTION — how deep it sits\n\nDimension the elevation at BOTH ends. State your scale.\n\n**Hand It Over**\n\nTrade drawings. The reader may not ask you anything until they are done. Every question they end up having to ask is a dimension you left off.\n\n**Questions**\n\n**What Was Missing**"}, {"id": "b5", "type": "self_assessment", "capture": true, "targetIds": ["tr.u2.slope-set", "tr.u2.rise-run", "tr.u2.slope-why", "tr.u2.fall-total", "tr.u2.plan-slope", "tr.u2.stair-sect"]}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s11', '3.1 · Why it is always the first riser and the last', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 11, 'markdown', true, 110, 1, true, array['I can explain why the end risers in a flight are the ones that end up wrong, and compare a spread to a code tolerance.']::text[], 'Cycle 3, session 1 of 5 — long.', '{"schemaVersion": 1, "dayType": "LAB", "blocks": [{"id": "b1", "type": "target", "statement": "I can explain why the end risers in a flight are the ones that end up wrong, and compare a spread to a code tolerance."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–15 | A month ago you measured every riser in that flight and the biggest and smallest did not match. The number is still in the box on the board. Today we find out what it means. |\n| 15–45 | The code: the greatest riser height in a flight may not exceed the smallest by more than 3/8 of an inch. Same for treads. Compare your spread. Does this school''s stair pass? |\n| 45–85 | Back to the stair. WHERE in the flight is the error? Almost always the first riser, the last, or both. The stringer was cut for equal risers — then finish floor went down at one end and not the other, and the whole error landed on the two risers nobody re-measured. Go and measure the finish floor thickness at top and bottom and see whether it accounts for the miss. |\n| 85–110 | Write the explanation. Not “it is off” — WHY it is off, WHERE the error went, and what would have prevented it. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Why It Is Always The First Riser And The Last\n\nWhere the error goes\n\nGo back to your numbers from 1.1\n\n**What**\n\n**Your Number**\n\nYour spread (biggest − smallest)\n\nCode limit\n\n3/8\"\n\nPASS or FAIL\n\nFinish floor thickness at the BOTTOM\n\nFinish floor thickness at the TOP\n\nExplain it\n\n1.  WHERE in the flight were the odd risers?\n\n2.  Does the finish floor thickness account for the miss?\n\n3.  The stringer was cut for equal risers. So WHERE did the error come from, and what would have prevented it?\n\nYou have seen this before. In Unit 1 you laid out sixteen on center and watched the error pile up at the far end. This is the same thing standing on its end."}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s12', '3.2 · Rack it', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 12, 'markdown', true, 55, 1, false, array['I can explain why a rectangle racks and a triangle does not, and say where a brace belongs.']::text[], 'Cycle 3, session 2 of 5 — short.', '{"schemaVersion": 1, "dayType": "STANDARD", "blocks": [{"id": "b1", "type": "target", "statement": "I can explain why a rectangle racks and a triangle does not, and say where a brace belongs."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Short session · ~55 min · one block", "markdown": "One movement. Your packet page for this session is on paper — do the work there."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–20 | Build a four-bar rectangle from cardboard strips with pinned corners. Push it. Now add one diagonal. Push it again. |\n| 20–40 | Why? A triangle''s shape is fixed by its three side lengths alone — there is only one triangle with those sides. A rectangle''s is not. That is the entire reason for sheathing, a let-in brace, a gusset, and the diagonal in a gate. |\n| 40–55 | Back to 1.5: you verified square with the diagonals. Now you know why the diagonal is the dimension that carries the information. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Rack It\n\nWhy a triangle holds\n\nAnswer these\n\n1.  Both frames have four sides of exactly the right length. Why does only one of them hold its shape?\n\n2.  Where does a brace have to go, and why THERE?\n\n3.  In 1.5 you checked square by measuring the diagonals. Now you know why the diagonal is the dimension that carries the information. Say it in your own words.\n\nSheathing, a let-in brace, a gusset plate, the diagonal in a gate — all the same idea, and you now know what the idea is."}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s13', '3.3 · The bay is already full', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 13, 'markdown', true, 110, 1, true, array['I can read a bay section and say which service has to move, and why.']::text[], 'Cycle 3, session 3 of 5 — long.', '{"schemaVersion": 1, "dayType": "LAB", "blocks": [{"id": "b1", "type": "target", "statement": "I can read a bay section and say which service has to move, and why."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–35 | One joist bay, three trades. The conduit is level and it got there first. The drain has to fall a quarter inch per foot. The joist can only be bored in its middle third. Read the section and find the collision. |\n| 35–75 | Route the drain. It will not fit as drawn. Your options are the real ones: deepen the joist, drop a soffit, move the conduit, move the fixture, or reduce the fall. Cost each one out in inches, not in opinions. |\n| 75–110 | Nobody in this drawing is wrong. Write the case for the trade you were assigned — not the trade you are in. Then hear the other two. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## The Bay Is Already Full\n\nThree trades, one joist bay\n\nFind the collision\n\n**What**\n\n**Your Number**\n\nJoist depth (actual)\n\nLength of the drain run\n\nTotal fall needed\n\nHeight of the conduit off the ceiling\n\nDoes the drain clear it?  By how much?\n\nFive real options — cost each one in inches\n\nDeepen the joist\n\nDrop a soffit below\n\nMove the conduit\n\nMove the fixture\n\nReduce the fall\n\nOne of those five works on the drawing and fails in the building two years later. Which one, and why?\n\nArgue the trade you were assigned — not the one you are in\n\nMy trade: ______________________\n\nWhat my trade needs, and why it is not negotiable:\n\nWhat I could give up, and what it would cost:\n\nNobody in that drawing is wrong. The conduit is level because conduit should be level. The drain falls because it has to. The joist is bored in the middle because that is where a hole does least harm. Somebody still has to move."}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s14', '3.4 · Call the fall', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 14, 'markdown', true, 55, 1, false, array['I can estimate a slope by eye and then check myself.']::text[], 'Cycle 3, session 4 of 5 — short.', '{"schemaVersion": 1, "dayType": "STANDARD", "blocks": [{"id": "b1", "type": "target", "statement": "I can estimate a slope by eye and then check myself."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Short session · ~55 min · one block", "markdown": "One movement. Your packet page for this session is on paper — do the work there."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–15 | Estimation call. Look at a run — a ramp, a gutter, a pipe, a parking lot — and write down your guess in inches per foot BEFORE you measure. Everybody commits on paper. |\n| 15–40 | Now measure it. High minus low, divided by the run. How close were you? Do it five times on five different things and watch your guesses get better. |\n| 40–55 | Marzano self-rating on the Cycle 3 targets. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n## Call The Fall\n\nGuess first. Then measure. Five times.\n\n**What You Looked At**\n\nMY CALL (in/ft)\n\n**Rise**\n\n**Run**\n\nACTUAL (in/ft)\n\n**Off By**\n\nWrite the guess down BEFORE the tape comes out. Watch the gap in the last column shrink as you go. That shrinking is the skill."}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('tu2-s15', '3.5 · Mastery task — route it and prove the fall', 'Unit 2: Plumb, Level, Square, Slope', 'trades-2', 15, 'markdown', true, 110, 1, true, array['I can route a run, prove the fall fits, and show what it costs the framing — or show that it cannot be done.']::text[], 'Cycle 3, session 5 of 5 — long.', '{"schemaVersion": 1, "dayType": "TRANSFER", "blocks": [{"id": "b1", "type": "target", "statement": "I can route a run, prove the fall fits, and show what it costs the framing — or show that it cannot be done."}, {"id": "b2", "type": "callout", "variant": "note", "title": "Long session · ~110 min · B and C", "markdown": "**Measure it. Draw it. Hand it over.** Your packet page for this session is on paper — do the work there. This page is the plan and the target."}, {"id": "b3", "type": "prose", "markdown": "### What happens today\n\n| Time | What happens |\n|---|---|\n| 0–20 | THE WALK. No task sheet yet. They look at a real bay — exposed ceiling, boiler room, anywhere services are visible — and fill in the scope sheet from what is in front of them. |\n| 20–35 | NOW hand out the task: a bay section, a fixture location, and a point of connection. Read the four scoring dimensions aloud. |\n| 35–75 | Work it. Total fall over the run. Does it clear the conduit? Does the bore land in the middle third? Is the fall still in code at both ends? Every claim gets a number beside it. |\n| 75–110 | Produce the drawing: plan with the fall called out, section with both end elevations and the bore located, scale stated. Then the written finding — it fits and here is the proof, or it does not fit and here is exactly what has to change and by how much. Self-score before handing in. |"}, {"id": "b4", "type": "prose", "markdown": "### From the packet\n\n**The Walk — before you price it, look at it**\n\nBefore you price it, look at it\n\nNobody prices a job off the phone call. You go and look first.\n\nToday the job is one joist bay with a fixture to connect. Go and look at a real bay — an exposed ceiling, the boiler room, anywhere the services are visible — before anybody hands you a section of one.\n\nFill this in BEFORE anybody hands you a drawing. You want your own read of the place before a piece of paper tells you what to expect — because once you have read the drawing, you will start seeing what it says instead of what is there.\n\n1.  WHAT THEY ASKED FOR\n\nIn their words, not yours. Write what you were actually told.\n\n2.  WHAT I FOUND WHEN I LOOKED\n\nConditions. What is really there — not what you expected to be there.\n\n3.  WHAT IT HAS TO DO TO BE CALLED DONE\n\nIf you cannot say this, you cannot tell when you have finished.\n\n4.  WHAT I AM STUCK WITH\n\nThe things you cannot change. Space, access, what is already installed, what somebody else owns.\n\n5.  WHAT CODE SAYS ABOUT IT\n\nSomebody already decided part of this for you. Write the number.\n\n6.  WHAT I AM NOT DOING\n\nThe line around the job. This is where people get burned.\n\n7.  WHAT I NEED TO KNOW BEFORE I START\n\nThe question you ask now instead of the mistake you make later.\n\nSign it\n\nWalked by ______________________\n\nDate ______________________\n\nA job you did not walk is a phone call. Everything on the rest of this task comes off this page.\n\n## Mastery Task — Route It And Prove The Fall\n\nThe task\n\nYou are given a bay section, a fixture, and the point where the drain has to connect. Route it, prove the fall, and show what it costs the framing.\n\nIf it does not fit, say so — and prove that too. “It cannot be done as drawn, and here is exactly what has to change and by how much” is a completely correct answer.\n\nProve it — every claim gets a number\n\n**What You Have To Show**\n\n**Your Number**\n\n**In / Out**\n\nLength of run\n\nSlope you are using (in/ft)\n\nTotal fall over that run\n\nDepth available in the bay\n\nClearance from the conduit\n\nBore lands in the middle third?\n\nPLAN — fall called out in a note, scale stated\n\nSECTION — both end elevations dimensioned, bore located, scale stated\n\nThe finding — write it so a foreman could act on it\n\n1. The answer.\n\nThis run FITS / DOES NOT FIT, and here is the number that decides it:\n\n2. The proof.\n\nOver ______ feet at ______ per foot the pipe falls ______, and the bay gives me ______.\n\n3. What it costs.\n\nTo make this work, ______________________ has to move, by ______, and that costs\n\n4. What I would not do.\n\nI did not reduce the fall, because\n\n5. My uncertainty.\n\nThe number I trust least here is ______________________, because\n\n**My Score 0–4**\n\nScience\n\nThe fall arithmetic is right and the depths are actual sizes, not nominal ones.\n\nReasoning\n\nYour resolution follows from your numbers, and you rejected the easy wrong answer for a stated reason.\n\nCommunication\n\nA tradesman could build from your plan and section without asking you anything.\n\nTransfer\n\nYou named what your decision costs another trade.\n\nYour grade is the LOWEST of the four. They are never averaged. You may revise within two weeks with new evidence."}, {"id": "b5", "type": "self_assessment", "capture": true, "targetIds": ["tr.u2.stair-why", "tr.u2.racking", "tr.u2.bay-conflict"]}, {"id": "b6", "type": "transfer_prompt", "masteryTaskSlug": "tr.u2.mastery-route-the-fall"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, published = excluded.published, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
