-- Trades Physics — Units 1 & 2 sessions as lessons. Generated from the MVP ETF Planning
-- lesson plans + student packets (docx). Idempotent: upsert by slug.
-- One lesson = one SESSION (one school day). LONG = B+C double (~110 min), SHORT = one block (~55 min).
-- transfer_core follows the units' own cut rule: 'drop a short, never a long' (+ Unit 2: never 2.4).



-- Unit windows: 15 sessions = 3 academic weeks. Trades cohort's first academic week is Sep 7, 2026 (opposite MVP CPA).
update public.units set allotted_days = 15, default_start_date = '2026-09-07' where id = 'trades-1';
update public.units set allotted_days = 15, default_start_date = '2026-10-19' where id = 'trades-2';
